import type { EngineInterface, Register } from 'claude-code'

import {
  ancestry,
  bestPerThread,
  briefFor,
  children,
  CLAUDE_MD,
  clip,
  type Hook,
  mark,
  parseJson,
  search,
  slug,
  type Thread,
  tree,
} from './lib'

type $ = EngineInterface
type Suggestion = { a: string; b: string; question: string }

const COMMANDS = {
  split: ['Split a new thread off this one into its own Claude tab or window', '<spark> [--new]'],
  find: ['Find a thread from a half-remembered fragment', '<fragment>'],
  threads: ['Show the thread tree', ''],
  thread: ['Show one thread: path, bookmark, hooks', '<id>'],
  pickup: ['Pick a paused thread back up in a new window', '<id> [full]'],
  bookmark: ["Refresh this thread's where-I-left-off", ''],
  pin: ['Pin the selection (or text) as a verbatim hook', '[text]'],
  link: ['Link two threads (or accept a /connect suggestion)', '<from> <to> | #<n>'],
  connect: ['Run a connections pass over all bookmarks', ''],
  'thread-open': ['Where /split and /pickup open: background agent, Claude tab, or new window', 'agent|tab|window'],
  'thread-archive': ['Archive a thread (moved to Threads/.archive; its children move up a level)', '<n|id>'],
  'thread-here': ['Make this session a thread (optionally under another)', '[title] [--under <n|id>]'],
} as const

// A suggested-restart match has to beat this score (see lib.search).
const RESTART_SCORE = 2.2

const BOOKMARK_ASK = `Write a bookmark for this conversation so a fresh agent (or the user, weeks from now) can pick it back up exactly where it stands. Plain markdown, at most 12 short lines, under these bold labels:
**In flight:** the question or idea being worked on right now.
**Next:** what was about to be tried.
**Picture:** the key image, result or claim in mind (say whether it is proven, observed in a sim, or a hunch).
**Artifacts:** files and artifact links that matter, with one-line purposes.
Do not summarise the whole history.`

export const register: Register = on => {
  on('session.start', async ($, e, next) => {
    const started = await next(e)
    const names: Record<string, string> = {}
    for (const [name, [description, argumentHint]] of Object.entries(COMMANDS)) {
      const spec = argumentHint ? { name, description, argumentHint } : { name, description }
      // A built-in may own the plain name; fall back to a prefixed one.
      names[name] = await $.command
        .register(spec)
        .then(r => r.command)
        .catch(() => $.command.register({ ...spec, name: `t-${name}` }).then(r => r.command))
    }
    await $.store.set('commandNames', names)
    await adopt($, e.cwd).catch(() => undefined)
    return started
  })

  // The user's own messages are the default hooks, kept verbatim.
  on('prompt.submit', async ($, e, next) => {
    if (!e.command && !e.isMeta && e.text.trim()) {
      const id = await currentId($)
      if (id) await addHook($, id, { at: now(), text: e.text, by: 'user' }).catch(() => undefined)
      // A tab opened by /split or /pickup starts in the project folder; its first prompt names the brief.
      else await adoptByBrief($, e.text).catch(() => undefined)
    }
    return next(e)
  }).catch(($, e, next) => next(e))

  on('session.end', async ($, e, next) => {
    const id = await currentId($)
    if (id && e.reason !== 'clear') {
      const t = await load($, id)
      if (t) {
        await bookmarkFromFork($, id).catch(() => undefined)
        await save($, { ...t, status: 'paused' })
      }
    }
    return next(e)
  })

  on('command.run', { command: ['split', 't-split'] }, async ($, e) => ({ text: await split($, e.args) })).catch(oops)
  on('command.run', { command: ['find', 't-find'] }, async ($, e) => ({ text: await find($, e.args, e.presentation.columns) })).catch(oops)
  on('command.run', { command: ['threads', 't-threads'] }, async ($, e) => ({ text: await showTree($, e.presentation.columns) })).catch(oops)
  on('command.run', { command: ['thread', 't-thread'] }, async ($, e) => ({ text: await showThread($, e.args.trim(), e.presentation.columns) })).catch(oops)
  on('command.run', { command: ['pickup', 't-pickup'] }, async ($, e) => ({ text: await pickup($, e.args) })).catch(oops)
  on('command.run', { command: ['bookmark', 't-bookmark'] }, async $ => ({ text: await refreshBookmark($) })).catch(oops)
  on('command.run', { command: ['thread-open', 't-thread-open'] }, async ($, e) => ({ text: await setOpenIn($, e.args.trim()) })).catch(oops)
  on('command.run', { command: ['thread-here', 't-thread-here'] }, async ($, e) => ({ text: await threadHere($, e.args.trim()) })).catch(oops)
  on('command.run', { command: ['thread-archive', 't-thread-archive'] }, async ($, e) => ({ text: await archive($, e.args.trim()) })).catch(oops)
  on('command.run', { command: ['pin', 't-pin'] }, async ($, e) => ({ text: await pin($, e.args) })).catch(oops)
  on('command.run', { command: ['link', 't-link'] }, async ($, e) => ({ text: await link($, e.args) })).catch(oops)
  on('command.run', { command: ['connect', 't-connect'] }, async $ => ({ text: await connect($) })).catch(oops)
}

// A failed command still answers, with the reason.
const oops = (_$: $, _e: unknown, next: { error: { kind: string; message?: string } }) => ({
  text: `threads: that failed (${next.error.message ?? next.error.kind}).`,
})

// ---- storage ----

async function root($: $): Promise<string> {
  const home = ((await $.env.get('USERPROFILE')) ?? (await $.env.get('HOME')) ?? '.').replace(/\\/g, '/')
  return `${home}/Documents/Projects/Threads`
}

async function dir($: $, id: string): Promise<string> {
  return `${await root($)}/${id}`
}

async function load($: $, id: string): Promise<Thread | undefined> {
  const text = await $.fs.read(`${await dir($, id)}/thread.json`).catch(() => undefined)
  return text === undefined ? undefined : (JSON.parse(text) as Thread)
}

async function save($: $, t: Thread): Promise<void> {
  await $.fs.write(`${await dir($, t.id)}/thread.json`, JSON.stringify({ ...t, updated: now() }, null, 2) + '\n')
}

async function all($: $): Promise<Record<string, Thread>> {
  const base = await root($)
  const entries = await $.fs.list(base).catch(() => [])
  const out: Record<string, Thread> = {}
  for (const entry of entries) {
    if (entry.kind !== 'dir') continue
    const t = await load($, entry.name)
    if (t) out[t.id] = t
  }
  return out
}

async function hooks($: $, id: string): Promise<Hook[]> {
  const text = await $.fs.read(`${await dir($, id)}/hooks.jsonl`).catch(() => '')
  return text
    .split('\n')
    .filter(Boolean)
    .map(line => JSON.parse(line) as Hook)
}

async function addHook($: $, id: string, hook: Hook): Promise<void> {
  const path = `${await dir($, id)}/hooks.jsonl`
  const prior = await $.fs.read(path).catch(() => '')
  await $.fs.write(path, prior + JSON.stringify(hook) + '\n')
}

async function bookmarkOf($: $, id: string): Promise<string | undefined> {
  return $.fs.read(`${await dir($, id)}/bookmark.md`).catch(() => undefined)
}

async function bookmarks($: $, ids: string[]): Promise<Record<string, string>> {
  const out: Record<string, string> = {}
  for (const id of ids) {
    const b = await bookmarkOf($, id)
    if (b) out[id] = b
  }
  return out
}

async function sessionMap($: $): Promise<Record<string, string>> {
  return ((await $.store.get('sessions')) as Record<string, string> | undefined) ?? {}
}

async function bind($: $, sessionId: string, threadId: string): Promise<void> {
  await $.store.set('sessions', { ...(await sessionMap($)), [sessionId]: threadId })
}

async function currentId($: $): Promise<string | undefined> {
  const sessionId = await $.session.id()
  const bound = (await sessionMap($))[sessionId]
  if (bound) return bound
  // Otherwise the most recently touched thread that lists this session.
  const owner = Object.values(await all($))
    .filter(t => t.sessions.some(s => s.id === sessionId))
    .sort((a, b) => b.updated.localeCompare(a.updated))[0]
  if (owner) await bind($, sessionId, owner.id)
  return owner?.id
}

// A session whose first prompt reads a thread's BRIEF.md belongs to that thread.
async function adoptByBrief($: $, text: string): Promise<void> {
  const base = (await root($)).toLowerCase()
  const flat = text.replace(/\\/g, '/')
  const at = flat.toLowerCase().indexOf(base + '/')
  if (at < 0) return
  const m = flat.slice(at + base.length + 1).match(/^([^/\s]+)\/BRIEF\.md/i)
  const t = m ? await load($, m[1]!) : undefined
  if (!t) return
  const sessionId = await $.session.id()
  await bind($, sessionId, t.id)
  await save($, { ...t, status: 'active', sessions: [...t.sessions, { id: sessionId, cwd: await $.session.cwd(), at: now() }] })
}

// A session started inside a thread folder belongs to that thread.
async function adopt($: $, cwd: string): Promise<void> {
  const base = (await root($)).toLowerCase()
  const here = cwd.replace(/\\/g, '/')
  if (!here.toLowerCase().startsWith(base + '/')) return
  const id = here.slice(base.length + 1).split('/')[0]!
  const t = await load($, id)
  if (!t) return
  const sessionId = await $.session.id()
  await bind($, sessionId, id)
  const sessions = t.sessions.some(s => s.id === sessionId) ? t.sessions : [...t.sessions, { id: sessionId, cwd, at: now() }]
  await save($, { ...t, status: 'active', sessions })
}

async function uniqueId($: $, title: string): Promise<string> {
  const base = slug(title)
  let id = base
  for (let n = 2; await $.fs.exists(`${await dir($, id)}/thread.json`); n++) id = `${base}-${n}`
  return id
}

async function create($: $, fields: Omit<Thread, 'id' | 'links' | 'created' | 'updated' | 'status'>): Promise<Thread> {
  const id = await uniqueId($, fields.title)
  const t: Thread = { id, links: [], created: now(), updated: now(), status: 'active', ...fields }
  const folder = await dir($, id)
  if (!t.workDir) t.workDir = folder
  await save($, t)
  await $.fs.write(`${folder}/CLAUDE.md`, CLAUDE_MD)
  return t
}

// ---- model calls ----

async function title($: $, text: string): Promise<string> {
  const r = await $.model.complete({
    model: 'haiku',
    effort: 'low',
    maxTokens: 40,
    timeoutMs: 15000,
    prompt: `Give a 2-4 word title for a research thread that starts with this message. Reply with the title alone, no quotes.\n\n<message>\n${text}\n</message>`,
  })
  return r.isAnswered && r.text.trim() ? clip(r.text.trim().replace(/^["']|["']$/g, ''), 40) : clip(text, 30)
}

async function bookmarkFromFork($: $, id: string): Promise<string | undefined> {
  const r = await $.model.fork({ prompt: BOOKMARK_ASK })
  if (!r.isAnswered) return undefined
  await $.fs.write(`${await dir($, id)}/bookmark.md`, r.text.trim() + '\n')
  return r.text.trim()
}

// ---- split: start an agent on the thread, in a Claude tab here or in a new VS Code window ----

type Launch = { prompt: string } | { session: string }

type OpenIn = 'agent' | 'tab' | 'window'

const OPEN_IN: Record<OpenIn, string> = {
  agent: 'a background session in the agent view (claude agents)',
  tab: 'a Claude Code tab in the current VS Code window',
  window: "a new VS Code window on the thread's folder",
}

async function openIn($: $): Promise<OpenIn> {
  const mode = await $.store.get('openIn')
  return mode === 'tab' || mode === 'window' ? mode : 'agent'
}

async function setOpenIn($: $, mode: string): Promise<string> {
  if (!(mode in OPEN_IN)) return `/split and /pickup open ${OPEN_IN[await openIn($)]}. Change it with /thread-open agent|tab|window.`
  await $.store.set('openIn', mode)
  return `/split and /pickup now open ${OPEN_IN[mode as OpenIn]}.`
}

async function openSplit($: $, t: Thread, launch: Launch, cwd: string): Promise<string> {
  const folder = await dir($, t.id)
  const win = (p: string) => p.replace(/\//g, '\\')
  const claudeArgs = 'session' in launch ? ['--resume', launch.session] : [launch.prompt]
  if (cwd !== folder && !('session' in launch)) claudeArgs.unshift('--add-dir', win(folder))
  const manual = `cd "${win(cwd)}" && claude ${claudeArgs.map(a => (/\s/.test(a) ? `"${a}"` : a)).join(' ')}`

  const mode = await openIn($)
  if (mode === 'agent') {
    // A background session shows up in `claude agents`; switch to it there.
    const name = `thread: ${t.title}`
    const bg = await $.process
      .run(['claude', '--bg', '-n', name, ...claudeArgs], { cwd: win(cwd), timeoutMs: 60000 })
      .catch((error: unknown) => ({ exitCode: -1, stdout: '', stderr: String(error) }))
    const said = `${bg.stdout}\n${bg.stderr}`.trim()
    if (/not trusted/i.test(said)) {
      return `Claude Code hasn't trusted ${win(cwd)} yet. Run claude there once and accept the trust prompt, then /pickup ${t.id}.`
    }
    return bg.exitCode === 0
      ? `Started "${name}" in the background. Open the agent view (claude agents) to switch to it, or: claude attach "${name}"`
      : `Couldn't start a background session (${clip(said, 200)}). Start it yourself:\n  ${manual}`
  }

  if (mode === 'tab') {
    // The Claude Code extension's own link opens a new Claude tab in the focused window.
    const query = 'session' in launch ? `session=${encodeURIComponent(launch.session)}` : `prompt=${encodeURIComponent(launch.prompt)}`
    const opened = await $.process.run(['explorer.exe', `vscode://anthropic.claude-code/open?${query}`], { timeoutMs: 20000 }).catch(() => undefined)
    return opened
      ? `Opened a Claude tab in this VS Code window. If the prompt is only filled in, press Enter.\n  /thread-open window switches back to separate windows. If no tab appeared, run:\n  ${manual}`
      : `Couldn't open a Claude tab. Start it yourself:\n  ${manual}`
  }

  const tasks = {
    version: '2.0.0',
    tasks: [
      {
        label: `claude: ${t.title}`,
        type: 'process',
        command: 'claude',
        args: claudeArgs,
        options: { cwd: win(cwd) },
        runOptions: { runOn: 'folderOpen' },
        presentation: { reveal: 'always', panel: 'dedicated', focus: true },
        problemMatcher: [],
      },
    ],
  }
  await $.fs.write(`${folder}/.vscode/tasks.json`, JSON.stringify(tasks, null, 2) + '\n')
  const opened = await $.process.run(['cmd', '/c', 'code', win(folder)], { timeoutMs: 20000 }).catch(() => undefined)
  return opened?.exitCode === 0
    ? `Opened a new VS Code window on ${win(folder)}.\n  If claude doesn't start there, set "task.allowAutomaticTasks": "on" or run:\n  ${manual}`
    : `Couldn't open VS Code. Start it yourself:\n  ${manual}`
}

async function startPrompt($: $, t: Thread): Promise<string> {
  return `Read ${await dir($, t.id)}/BRIEF.md, then tell me in a few lines where this thread starts from and what you would look at first.`
}

// Make this session a thread: its first message is the spark, all of the user's messages its hooks.
async function threadFromSession($: $, opts: { title?: string; parent?: string; fallbackSpark?: string }): Promise<Thread> {
  const mine = (await $.session.messages()).filter(m => m.role === 'user' && m.text.trim() && !m.text.startsWith('<'))
  const first = mine[0]?.text ?? opts.fallbackSpark ?? ''
  const cwd = await $.session.cwd()
  const t = await create($, {
    title: opts.title || (await title($, first)),
    spark: first,
    parent: opts.parent ?? null,
    workDir: cwd.replace(/\\/g, '/'),
    sessions: [{ id: await $.session.id(), cwd, at: now() }],
  })
  for (const m of mine) await addHook($, t.id, { at: now(), text: m.text, by: 'user' })
  await bind($, await $.session.id(), t.id)
  return t
}

// ---- commands ----

async function threadHere($: $, args: string): Promise<string> {
  const already = await currentId($)
  if (already) return `This session is already the thread [${already}]. /thread for its details.`
  const under = args.match(/(?:^|\s)--under\s+(\S+)/)
  const threads = await all($)
  const parent = under ? await resolve($, under[1]!) : undefined
  if (parent && !threads[parent]) return `No thread "${under![1]}" to put it under. /threads to look.`
  const name = args.replace(/(?:^|\s)--under\s+\S+/, '').trim()
  const t = await threadFromSession($, { title: name || undefined, parent })
  const hookCount = (await hooks($, t.id)).length
  const marked = await bookmarkFromFork($, t.id).catch(() => undefined)
  return [
    `This session is now the thread ${t.title}  [${t.id}]${parent ? `  ← under ${threads[parent]!.title}` : ''}`,
    `  spark: "${clip(t.spark, 90)}"`,
    `  ${hookCount} of your messages saved as hooks; ${marked ? 'bookmark written' : 'no bookmark yet (run /bookmark)'}.`,
  ].join('\n')
}

async function split($: $, args: string): Promise<string> {
  const isForced = /(^|\s)--new(\s|$)/.test(args)
  let spark = args.replace(/(^|\s)--new(\s|$)/, ' ').trim()
  if (!spark) spark = (await $.ui.selection())?.text.trim() ?? ''
  if (!spark) {
    const mine = (await $.session.messages()).filter(m => m.role === 'user' && m.text.trim() && !m.text.startsWith('<'))
    spark = mine.at(-1)?.text.trim() ?? ''
  }
  if (!spark) return 'Give the spark: /split <what started this>'

  const threads = await all($)
  if (!isForced) {
    const match = await restartMatch($, spark, threads)
    if (match) return match
  }

  // The thread we're leaving: this session's, or a new one for an untracked session.
  let parentId = await currentId($)
  if (!parentId) {
    const parent = await threadFromSession($, { fallbackSpark: spark })
    parentId = parent.id
    threads[parentId] = parent
  }

  const fork = await $.model.fork({
    prompt: `The user is splitting a new research thread off this conversation. Its spark, in their words:\n<spark>\n${spark}\n</spark>\nReply with JSON only: {"bookmark": "...", "handoff": "..."}.\n"bookmark": ${BOOKMARK_ASK}\n"handoff": what a fresh agent starting the new thread needs from THIS conversation to pursue the spark, at most 10 lines of markdown. Only what bears on the spark.`,
  })
  const parsed = fork.isAnswered ? parseJson<{ bookmark?: string; handoff?: string }>(fork.text) : undefined
  if (parsed?.bookmark) await $.fs.write(`${await dir($, parentId)}/bookmark.md`, parsed.bookmark.trim() + '\n')

  const child = await create($, { title: await title($, spark), spark, parent: parentId, workDir: '', sessions: [] })
  threads[child.id] = child
  await addHook($, child.id, { at: now(), text: spark, by: 'user' })
  const path = ancestry(child.id, threads)
  const brief = briefFor(child, threads, await bookmarks($, path.map(p => p.id)), parsed?.handoff)
  await $.fs.write(`${await dir($, child.id)}/BRIEF.md`, brief)
  const opened = await openSplit($, child, { prompt: await startPrompt($, child) }, await dir($, child.id))

  return [
    `Bookmarked: ${threads[parentId]!.title}${parsed?.bookmark ? '' : ' (no bookmark: the fork call failed; run /bookmark)'}`,
    `New thread: ${child.title}  [${child.id}]  ← from ${threads[parentId]!.title}`,
    `  "${clip(spark, 90)}"`,
    `  brief: spark + ${path.length - 1} ancestor bookmark(s), ~${Math.round(brief.length / 4)} tokens`,
    opened,
  ].join('\n')
}

async function restartMatch($: $, spark: string, threads: Record<string, Thread>): Promise<string | undefined> {
  const corpus = await corpusOf($, threads)
  const titles = Object.fromEntries(Object.values(threads).map(t => [t.id, t.title]))
  // One shared word ("test") is a coincidence, not a restart.
  const top = bestPerThread(search(spark, corpus, titles), 2).filter(h => h.score >= RESTART_SCORE && h.shared >= 3)
  if (!top.length) return undefined
  const names = (await $.store.get('commandNames')) as Record<string, string> | undefined
  const lines = ['This looks like a thread you already started:']
  for (const h of top) {
    const t = threads[h.thread]!
    lines.push(`  ${t.title} ${mark(t)}  [${t.id}]`, `    "${clip(h.hook.text, 90)}"`)
  }
  lines.push(
    '',
    `/${names?.pickup ?? 'pickup'} ${top[0]!.thread} to resume it, /${names?.link ?? 'link'} to connect, or /${names?.split ?? 'split'} --new ${clip(spark, 30)} to start fresh anyway.`,
  )
  return lines.join('\n')
}

async function corpusOf($: $, threads: Record<string, Thread>): Promise<{ thread: string; hook: Hook }[]> {
  const corpus: { thread: string; hook: Hook }[] = []
  for (const id of Object.keys(threads)) for (const hook of await hooks($, id)) corpus.push({ thread: id, hook })
  return corpus
}

// `/thread 3` and `/pickup 3` mean the 3rd entry of the last /threads or /find listing.
async function resolve($: $, ref: string): Promise<string> {
  const n = ref.match(/^#?(\d+)$/)
  if (!n) return ref
  const listing = ((await $.store.get('listing')) as string[] | undefined) ?? []
  return listing[Number(n[1]) - 1] ?? ref
}

async function find($: $, fragment: string, columns: number): Promise<string> {
  if (!fragment.trim()) return 'What do you remember? /find <fragment>'
  const threads = await all($)
  const titles = Object.fromEntries(Object.values(threads).map(t => [t.id, t.title]))
  const hits = bestPerThread(search(fragment, await corpusOf($, threads), titles), 6)
  if (!hits.length) return `Nothing matched "${fragment}". Try other words you remember, or /threads for the whole tree.`
  await $.store.set('listing', hits.map(h => h.thread))
  const room = Math.max(40, columns - 8)
  const lines = [`Matches for "${clip(fragment, 40)}":`]
  hits.forEach((h, i) => {
    const t = threads[h.thread]!
    lines.push(clip(`${i + 1}. ${t.title} ${mark(t)}  [${t.id}]`, room), `   "${clip(h.hook.text, room - 5)}"`)
  })
  lines.push('', '/thread <n> for its path and bookmark, /pickup <n> to switch to it.')
  return lines.join('\n')
}

async function showTree($: $, columns: number | undefined): Promise<string> {
  const threads = await all($)
  if (!Object.keys(threads).length) return 'No threads yet. /split <spark> starts one.'
  const first: Record<string, string> = {}
  for (const id of Object.keys(threads)) first[id] = (await hooks($, id))[0]?.text ?? threads[id]!.spark
  const { text, order } = tree(threads, first, columns ?? 100)
  await $.store.set('listing', order)
  return [
    `${order.length} threads. /thread <n> to look closer, /pickup <n> to switch to one.`,
    '',
    text,
    '',
    '● active  ⏸ paused  ↩ your links (* = from a connections pass)',
  ].join('\n')
}

async function showThread($: $, ref: string, columns: number): Promise<string> {
  const threads = await all($)
  const id = await resolve($, ref)
  const room = Math.max(40, columns - 8)
  const t = threads[id || ((await currentId($)) ?? '')]
  if (!t) return id ? `No thread "${id}". /find or /threads to look.` : 'This session is not in a thread. /thread <id>'
  const path = ancestry(t.id, threads)
  const kids = children(t.id, threads)
  const backs = Object.values(threads).filter(o => o.links.some(l => l.to === t.id))
  const hs = await hooks($, t.id)
  return [
    `${t.title} ${mark(t)}  [${t.id}]`,
    `  how you got here:  ${path.map(p => p.title).join(' → ')}`,
    `  where it went:     ${kids.length ? kids.map(k => `→ ${k.title}`).join(', ') : '(nothing yet)'}`,
    ...(t.links.length || backs.length
      ? [`  links:             ${[...t.links.map(l => threads[l.to]?.title ?? l.to), ...backs.map(b => b.title)].join(', ')}`]
      : []),
    '',
    'Left off:',
    ((await bookmarkOf($, t.id)) ?? '(no bookmark yet)').trim().replace(/^/gm, '  '),
    '',
    `Hooks (${hs.length}, latest last):`,
    ...hs.slice(-5).map(h => `  ${h.by === 'pin' ? '📌' : '›'} "${clip(h.text, room - 6)}"`),
    '',
    `/pickup ${t.id} to resume here (fresh agent from the bookmark), /pickup ${t.id} full to reopen its last session.`,
  ].join('\n')
}

async function pickup($: $, args: string): Promise<string> {
  const [ref = '', mode] = args.trim().split(/\s+/)
  const threads = await all($)
  const id = await resolve($, ref)
  const t = threads[id]
  if (!t) return `No thread "${id}". /find <fragment> to look for it.`
  if (mode === 'full') {
    const last = t.sessions.at(-1)
    if (!last) return `${t.title} has no recorded session. /pickup ${t.id} starts a fresh agent from its bookmark.`
    return openSplit($, t, { session: last.id }, last.cwd)
  }
  const path = ancestry(t.id, threads)
  await $.fs.write(`${await dir($, t.id)}/BRIEF.md`, briefFor(t, threads, await bookmarks($, path.map(p => p.id))))
  const opened = await openSplit($, t, { prompt: await startPrompt($, t) }, t.workDir || (await dir($, t.id)))
  return `Picking up ${t.title}.\n${opened}`
}

async function refreshBookmark($: $): Promise<string> {
  const id = await currentId($)
  if (!id) return 'This session is not in a thread yet. /split makes it one.'
  const text = await bookmarkFromFork($, id)
  return text ? `Bookmark saved for ${id}:\n${text.replace(/^/gm, '  ')}` : 'The bookmark call failed; try again.'
}

async function pin($: $, args: string): Promise<string> {
  const id = await currentId($)
  if (!id) return 'This session is not in a thread yet. /split makes it one.'
  const text = args.trim() || (await $.ui.selection())?.text.trim()
  if (!text) return 'Select a line (or pass text) to pin.'
  await addHook($, id, { at: now(), text, by: 'pin' })
  return `Pinned to ${id}: "${clip(text, 100)}"`
}

// Archive rather than delete: the folder moves to Threads/.archive, so it can come back.
async function archive($: $, ref: string): Promise<string> {
  if (!ref) return 'Usage: /thread-archive <n|id>. Numbers come from the last /threads or /find.'
  const threads = await all($)
  const id = await resolve($, ref)
  const t = threads[id]
  if (!t) return `No thread "${id}". /threads to look.`

  const from = (await dir($, id)).replace(/\//g, '\\')
  const shelf = `${await root($)}/.archive`
  await $.fs.write(`${shelf}/README.md`, 'Archived threads. Move a folder back up one level to restore it.\n')
  const to = `${shelf}/${id}-${now().slice(0, 10)}`.replace(/\//g, '\\')
  const moved = await $.process.run(['cmd', '/c', 'move', from, to], { timeoutMs: 20000 }).catch(() => undefined)
  if (moved?.exitCode !== 0) {
    return `Couldn't move ${from} (${clip(`${moved?.stdout ?? ''} ${moved?.stderr ?? ''}`.trim() || 'unknown error', 120)}). If a session is running in that folder, stop it first (claude agents).`
  }

  // Keep the tree whole: children move up to the archived thread's parent; links to it go.
  const kids = children(id, threads)
  for (const other of Object.values(threads)) {
    if (other.id === id) continue
    const isKid = other.parent === id
    const links = other.links.filter(l => l.to !== id)
    if (isKid || links.length !== other.links.length) await save($, { ...other, parent: isKid ? t.parent : other.parent, links })
  }
  const map = await sessionMap($)
  await $.store.set('sessions', Object.fromEntries(Object.entries(map).filter(([, tid]) => tid !== id)))

  const up = t.parent ? threads[t.parent]?.title : 'the top level'
  return [
    `Archived ${t.title} [${id}] to ${to}.`,
    ...(kids.length ? [`  ${kids.map(k => k.title).join(', ')} moved up to ${up}.`] : []),
    '  To restore it, move the folder back into Threads.',
  ].join('\n')
}

async function link($: $, args: string): Promise<string> {
  const threads = await all($)
  const pick = args.trim().match(/^#(\d+)$/)
  let from: string, to: string, by: 'user' | 'pass', note: string | undefined
  if (pick) {
    const s = (((await $.store.get('suggestions')) as Suggestion[] | undefined) ?? [])[Number(pick[1]) - 1]
    if (!s) return `No suggestion #${pick[1]}. /connect lists them.`
    ;({ a: from, b: to, question: note } = s)
    by = 'pass'
  } else {
    const parts = args.trim().split(/\s+/)
    if (parts.length < 2) return 'Usage: /link <from-id> <to-id>, or /link #<n> to accept a /connect suggestion.'
    ;[from, to] = parts as [string, string]
    by = 'user'
  }
  const a = threads[from]
  if (!a || !threads[to]) return `Unknown thread: ${!a ? from : to}`
  if (!a.links.some(l => l.to === to)) await save($, { ...a, links: [...a.links, { to, by, ...(note ? { note } : {}) }] })
  return `Linked ${a.title} ↩ ${threads[to]!.title}${by === 'pass' ? ' (from a connections pass)' : ''}`
}

async function connect($: $): Promise<string> {
  const threads = await all($)
  const ids = Object.keys(threads)
  if (ids.length < 2) return 'Need at least two threads.'
  const marks = await bookmarks($, ids)
  const cards: string[] = []
  for (const t of Object.values(threads)) {
    const hs = (await hooks($, t.id)).filter(h => h.by === 'pin' || h.text.length > 40)
    const quotes = [hs[0], ...hs.slice(1).filter(h => h.by === 'pin').slice(0, 2)].filter(Boolean) as Hook[]
    const edges = [t.parent ? `parent ${t.parent}` : '', ...t.links.map(l => `linked ${l.to}`)].filter(Boolean).join('; ')
    cards.push(`## ${t.id}: ${t.title}${edges ? ` (${edges})` : ''}\n${quotes.map(q => `> ${clip(q.text, 300)}`).join('\n')}\n${clip(marks[t.id] ?? '', 900)}`)
  }
  const r = await $.model.complete({
    model: 'sonnet',
    maxTokens: 1500,
    timeoutMs: 90000,
    prompt: `These are threads from the user's research graph. Find up to 5 connections between threads that are NOT already parent/child or linked: places where one thread's idea, mechanism or result might bear on another. Phrase each as a short question to the user, not a conclusion; they decide. Reply with a JSON array only: [{"a": "<id>", "b": "<id>", "question": "..."}].\n\n${cards.join('\n\n')}`,
  })
  const list = (r.isAnswered ? parseJson<Suggestion[]>(r.text) : undefined)?.filter(s => threads[s.a] && threads[s.b]) ?? []
  if (!list.length) return r.isAnswered ? 'No new connections suggested.' : `The connections pass failed (${r.reason}).`
  await $.store.set('suggestions', list)
  const stale = Object.values(threads)
    .filter(t => t.status === 'paused' && Date.now() - Date.parse(t.updated) > 14 * 864e5)
    .map(t => t.title)
  return [
    ...list.map((s, i) => `${i + 1}. ${threads[s.a]!.title} ↔ ${threads[s.b]!.title}\n   ${s.question}`),
    '',
    '/link #<n> to accept one; the rest are dropped at the next pass.',
    ...(stale.length ? ['', `Paused for over two weeks: ${stale.join(', ')}`] : []),
  ].join('\n')
}

function now(): string {
  return new Date().toISOString()
}

