// Pure helpers for the threads mod: no `$`, so tests can import them.

export type Link = { to: string; by: 'user' | 'pass'; note?: string }

export type SessionRef = { id: string; cwd: string; at: string }

export type Thread = {
  id: string
  title: string
  spark: string
  parent: string | null
  links: Link[]
  status: 'active' | 'paused'
  created: string
  updated: string
  workDir: string
  sessions: SessionRef[]
}

export type Hook = { at: string; text: string; by: 'user' | 'pin' }

export type Hit = { thread: string; hook: Hook; score: number; shared: number }

const STOP = new Set(
  ('a an and are as at be been but by can could do does did for from had has have how i if in into is it its ' +
    'just like me more my not of on or so some that the their then there these they this to was we were what ' +
    'when where which while who why will with would you your about also really think want get going one')
    .split(' '),
)

export function tokens(text: string): string[] {
  return (text.toLowerCase().match(/[a-z0-9]+/g) ?? [])
    .filter(t => t.length > 2 && !STOP.has(t))
    .map(stem)
}

// Crude stem so "circles"/"circle", "coupled"/"coupling" meet.
function stem(t: string): string {
  return t.replace(/(ings|ing|ed|es|s)$/, '') || t
}

export function slug(title: string): string {
  const base = title
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '')
    .slice(0, 40)
  return base || 'thread'
}

// Rank verbatim hooks against a half-remembered fragment, by shared rare words.
export function search(fragment: string, corpus: { thread: string; hook: Hook }[], titles: Record<string, string> = {}): Hit[] {
  const query = new Set(tokens(fragment))
  if (query.size === 0) return []
  const df = new Map<string, number>()
  const docs = corpus.map(c => new Set(tokens(c.hook.text + ' ' + (titles[c.thread] ?? ''))))
  for (const d of docs) for (const t of d) df.set(t, (df.get(t) ?? 0) + 1)
  const n = corpus.length
  const hits: Hit[] = []
  corpus.forEach((c, i) => {
    let score = 0
    let shared = 0
    for (const t of query) {
      if (!docs[i]!.has(t)) continue
      score += Math.log(1 + n / (df.get(t) ?? 1))
      shared++
    }
    if (score > 0) hits.push({ ...c, score: score / Math.sqrt(query.size), shared })
  })
  return hits.sort((a, b) => b.score - a.score)
}

// Best hit per thread, so one chatty thread doesn't crowd the list.
export function bestPerThread(hits: Hit[], limit: number): Hit[] {
  const seen = new Set<string>()
  const out: Hit[] = []
  for (const h of hits) {
    if (seen.has(h.thread)) continue
    seen.add(h.thread)
    out.push(h)
    if (out.length === limit) break
  }
  return out
}

export function clip(text: string, width: number): string {
  const flat = text.replace(/\s+/g, ' ').trim()
  return flat.length <= width ? flat : flat.slice(0, width - 1) + '…'
}

export function ancestry(id: string, all: Record<string, Thread>): Thread[] {
  const path: Thread[] = []
  let at: Thread | undefined = all[id]
  while (at && !path.includes(at)) {
    path.unshift(at)
    at = at.parent ? all[at.parent] : undefined
  }
  return path
}

export function children(id: string, all: Record<string, Thread>): Thread[] {
  return Object.values(all)
    .filter(t => t.parent === id)
    .sort((a, b) => a.created.localeCompare(b.created))
}

export function mark(t: Thread): string {
  return t.status === 'active' ? '●' : '⏸'
}

// Room the transcript takes for its own gutter beside a command's output.
const GUTTER = 8

// Each node gets a number (its place in this listing) so `/pickup 3` works.
export function tree(all: Record<string, Thread>, firstHook: Record<string, string>, width = 100): { text: string; order: string[] } {
  const roots = Object.values(all)
    .filter(t => !t.parent || !all[t.parent])
    .sort((a, b) => a.created.localeCompare(b.created))
  const room = Math.max(40, width - GUTTER)
  const lines: string[] = []
  const order: string[] = []
  const walk = (t: Thread, prefix: string, isLast: boolean, isRoot: boolean) => {
    order.push(t.id)
    const branch = isRoot ? '' : isLast ? '└─ ' : '├─ '
    const links = t.links.length ? `  ↩ ${t.links.map(l => l.to + (l.by === 'pass' ? '*' : '')).join(', ')}` : ''
    const head = `${prefix}${branch}${order.length}. ${t.title} ${mark(t)}  [${t.id}]${links}`
    lines.push(head.length <= room ? head : head.slice(0, room - 1) + '…')
    const childPrefix = prefix + (isRoot ? '' : isLast ? '   ' : '│  ')
    const kids = children(t.id, all)
    const quote = firstHook[t.id]
    if (quote) {
      const lead = `${childPrefix}${kids.length ? '│  ' : '   '}`
      lines.push(`${lead}"${clip(quote, Math.max(20, room - lead.length - 2))}"`)
    }
    kids.forEach((k, i) => walk(k, childPrefix, i === kids.length - 1, false))
  }
  roots.forEach(r => walk(r, '', true, true))
  return { text: lines.join('\n'), order }
}

// Pull the first JSON object or array out of a model reply.
export function parseJson<T>(text: string): T | undefined {
  const start = text.search(/[[{]/)
  if (start < 0) return undefined
  for (let end = text.length; end > start; end--) {
    const ch = text[end - 1]
    if (ch !== '}' && ch !== ']') continue
    try {
      return JSON.parse(text.slice(start, end)) as T
    } catch {
      // keep shrinking
    }
  }
  return undefined
}

export function briefFor(t: Thread, all: Record<string, Thread>, bookmarks: Record<string, string>, handoff?: string): string {
  const path = ancestry(t.id, all)
  const out = [
    `# Brief: ${t.title}`,
    '',
    `Thread \`${t.id}\`. Path: ${path.map(p => p.title).join(' → ')}`,
    '',
    '## Spark (verbatim, from the user)',
    '',
    t.spark
      .split('\n')
      .map(l => `> ${l}`)
      .join('\n'),
    '',
  ]
  if (handoff) out.push('## Handed over from the parent conversation', '', handoff.trim(), '')
  if (bookmarks[t.id]) out.push('## Where this thread left off', '', bookmarks[t.id]!.trim(), '')
  const elders = path.slice(0, -1).reverse()
  if (elders.length) {
    out.push('## Where the threads it came from left off', '')
    for (const e of elders) out.push(`### ${e.title} (\`${e.id}\`)`, '', (bookmarks[e.id] ?? '(no bookmark yet)').trim(), '')
  }
  return out.join('\n')
}

export const CLAUDE_MD = `# Research thread

This folder is one thread in the user's research graph. Start by reading BRIEF.md.

- Stay inside this thread. Don't read sibling thread folders (\`../*\`) unless the user asks; that's the point of the split.
- The user likes discursive tangents and makes the connections between threads themselves. Don't volunteer links to other threads.
- Put work files for this thread in this folder.
- \`/bookmark\` refreshes where-I-left-off, \`/split <spark>\` splits off a new thread, \`/find <fragment>\` locates an old one.
`

